def find_missing_numbers(lst, lo, hi):
    present = set(lst)
    return [x for x in range(lo, hi + 1) if x not in present]

def find_duplicates_only(lst):
    from collections import Counter
    counts = Counter(lst)
    seen = set()
    out = []
    for x in lst:
        if counts[x] > 1 and x not in seen:
            seen.add(x)
            out.append(x)
    return out

def is_balanced_brackets(tokens):
    depth = 0
    for t in tokens:
        if t == '(':
            depth += 1
        else:
            depth -= 1
        if depth < 0:
            return False
    return depth == 0

def alternating_sum(lst):
    total = 0
    for i, x in enumerate(lst):
        if i % 2 == 0:
            total += x
        else:
            total -= x
    return total

def chunk_by_predicate_change(lst):
    if not lst:
        return []
    out = []
    current = [lst[0]]
    prev_even = lst[0] % 2 == 0
    for x in lst[1:]:
        even = x % 2 == 0
        if even == prev_even:
            current.append(x)
        else:
            out.append(current)
            current = [x]
            prev_even = even
    out.append(current)
    return out

def shift_and_fill(lst, k, fill):
    n = len(lst)
    if k >= n:
        return [fill] * n
    return [fill] * k + lst[:n - k]

def interleave_chunks(a, b, k):
    out = []
    i = j = 0
    turn_a = True
    while i < len(a) or j < len(b):
        if turn_a:
            if i < len(a):
                out.extend(a[i:i+k])
                i += k
        else:
            if j < len(b):
                out.extend(b[j:j+k])
                j += k
        turn_a = not turn_a
    return out

def count_plateaus(lst):
    if not lst:
        return 0
    count = 1
    for i in range(1, len(lst)):
        if lst[i] != lst[i - 1]:
            count += 1
    return count
